import React, { useState, useEffect } from 'react';
import { FaMoneyBillWave, FaInfoCircle } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import Modal from './Modal';

const BudgetModal = ({ isOpen, onClose, onComplete, initialBudget }) => {
  const { theme } = useTheme();
  const [showTooltip, setShowTooltip] = useState(false);
  const [budget, setBudget] = useState(initialBudget || '');
  const [leeway, setLeeway] = useState(10); // Default 10% leeway
  const [currency, setCurrency] = useState('USD');

  // Common currencies with their symbols
  const currencies = {
    USD: { symbol: '$', name: 'US Dollar' },
    EUR: { symbol: '€', name: 'Euro' },
    GBP: { symbol: '£', name: 'British Pound' },
    JPY: { symbol: '¥', name: 'Japanese Yen' },
    AUD: { symbol: 'A$', name: 'Australian Dollar' },
    CAD: { symbol: 'C$', name: 'Canadian Dollar' },
    CHF: { symbol: 'Fr', name: 'Swiss Franc' },
    CNY: { symbol: '¥', name: 'Chinese Yuan' },
    INR: { symbol: '₹', name: 'Indian Rupee' },
    SGD: { symbol: 'S$', name: 'Singapore Dollar' }
  };

  useEffect(() => {
    if (initialBudget) {
      setBudget(initialBudget);
    }
  }, [initialBudget]);

  const handleBudgetChange = (e) => {
    const value = e.target.value.replace(/[^0-9]/g, '');
    setBudget(value);
  };

  const handleLeewayChange = (e) => {
    const value = Math.min(Math.max(0, parseInt(e.target.value) || 0), 100);
    setLeeway(value);
  };

  const handleComplete = () => {
    if (budget) {
      onComplete({
        amount: parseInt(budget),
        leeway,
        currency
      });
      onClose();
    }
  };

  const formatAmount = (amount, currency) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  const maxBudget = budget ? parseInt(budget) * (1 + leeway / 100) : 0;

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Set Your Budget">
      <div className="space-y-6">
        <div className="flex items-center space-x-4">
          <FaMoneyBillWave style={{ color: theme.primary }} className="text-xl" />
          <h2 className="text-xl font-semibold" style={{ color: theme.text }}>Budget Details</h2>
        </div>

        {/* Budget Input */}
        <div className="space-y-2">
          <div className="flex items-center space-x-2">
            <label className="block text-sm font-medium" style={{ color: theme.text }}>
              Budget Amount
            </label>
            <div className="relative">
              <button
                onMouseEnter={() => setShowTooltip(true)}
                onMouseLeave={() => setShowTooltip(false)}
                className="focus:outline-none"
                style={{ color: theme.textLight }}
              >
                <FaInfoCircle className="text-lg" />
              </button>
              
              {showTooltip && (
                <div 
                  className="absolute z-10 w-72 p-4 rounded-lg shadow-lg transform -translate-x-1/2 left-1/2 mt-2"
                  style={{ 
                    backgroundColor: theme.background,
                    border: `1px solid ${theme.border}`,
                    color: theme.text
                  }}
                >
                  <p className="text-sm leading-relaxed">
                    Set your base budget and add a leeway percentage to allow for flexibility in your spending. The total budget will be automatically converted to your destination's currency.
                  </p>
                  <div 
                    className="absolute w-3 h-3 transform rotate-45 -top-2 left-1/2 -translate-x-1/2"
                    style={{ backgroundColor: theme.background, borderLeft: `1px solid ${theme.border}`, borderTop: `1px solid ${theme.border}` }}
                  />
                </div>
              )}
            </div>
          </div>

          <div className="flex space-x-4">
            <select
              value={currency}
              onChange={(e) => setCurrency(e.target.value)}
              className="w-32 p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
              style={{ 
                borderColor: theme.border,
                backgroundColor: theme.background,
                color: theme.text
              }}
            >
              {Object.entries(currencies).map(([code, { symbol, name }]) => (
                <option key={code} value={code}>
                  {code} ({symbol})
                </option>
              ))}
            </select>

            <div className="flex-1 relative">
              <span 
                className="absolute left-3 top-1/2 transform -translate-y-1/2"
                style={{ color: theme.textLight }}
              >
                {currencies[currency].symbol}
              </span>
              <input
                type="text"
                value={budget}
                onChange={handleBudgetChange}
                placeholder="Enter amount"
                className="w-full p-2 pl-8 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
                style={{ 
                  borderColor: theme.border,
                  backgroundColor: theme.background,
                  color: theme.text,
                  '::placeholder': {
                    color: theme.textLight
                  }
                }}
              />
            </div>
          </div>
        </div>

        {/* Leeway Slider */}
        <div className="space-y-2">
          <div className="flex justify-between items-center">
            <label className="block text-sm font-medium" style={{ color: theme.text }}>
              Budget Leeway
            </label>
            <span style={{ color: theme.textLight }}>{leeway}%</span>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={leeway}
            onChange={handleLeewayChange}
            className="w-full"
            style={{ 
              accentColor: theme.primary
            }}
          />
          <p className="text-sm" style={{ color: theme.textLight }}>
            Allows for flexibility in your spending
          </p>
        </div>

        {/* Budget Summary */}
        {budget && (
          <div className="p-4 rounded-lg" style={{ backgroundColor: theme.background }}>
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <span style={{ color: theme.textLight }}>Base Budget</span>
                <span style={{ color: theme.text }}>
                  {formatAmount(parseInt(budget), currency)}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span style={{ color: theme.textLight }}>Maximum Budget</span>
                <span style={{ color: theme.text }}>
                  {formatAmount(maxBudget, currency)}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex justify-end space-x-4 mt-8">
          <button
            onClick={onClose}
            className="px-6 py-2 border rounded-lg transition-colors"
            style={{ 
              borderColor: theme.border,
              color: theme.text,
              backgroundColor: theme.background,
              ':hover': {
                backgroundColor: theme.backgroundAlt
              }
            }}
          >
            Cancel
          </button>
          <button
            onClick={handleComplete}
            disabled={!budget}
            className={`px-6 py-2 rounded-lg transition-colors ${
              budget
                ? 'hover:opacity-90'
                : 'opacity-50 cursor-not-allowed'
            }`}
            style={{ 
              backgroundColor: budget ? theme.primary : theme.accent,
              color: theme.background
            }}
          >
            Confirm
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default BudgetModal;
